\copy (SELECT le.id AS ledger_entry_id,l.id AS ledger_id,l.name AS ledger_name,l.category::text AS ledger_category,v.id AS voucher_id,v."voucherNo" AS voucher_no,((v."voucherDate" AT TIME ZONE 'UTC') AT TIME ZONE 'Asia/Kolkata')::date AS local_date,v."voucherType"::text AS voucher_type,le."entryType"::text AS side,le.amount,le.narration AS entry_narration,v.narration AS voucher_narration,v."totalDebit" AS total_debit,v."totalCredit" AS total_credit,(SELECT string_agg(DISTINCT j."sourceSheet", ',') FROM "Journal" j WHERE j."voucherId"=v.id) AS source_sheets FROM "LedgerEntry" le JOIN "Ledger" l ON l.id=le."ledgerId" JOIN "LedgerGroup" g ON g.id=l."groupId" JOIN "Voucher" v ON v.id=le."voucherId" WHERE l."branchId"='47fdc8aa-83ba-46f9-93ec-4517e0eb13bb' AND g.name ILIKE '%Sundry Debtor%' ORDER BY l.name,local_date,v."voucherNo",le.id) TO '.tmp-debtor-db.csv' WITH (FORMAT csv, HEADER true);
